    for (i = 0; i < KEY_NAMES.length; i++) {
        KEYS[KEY_NAMES[i]] = PREFIX_NEW + KEY_NAMES[i];
        LEGACY_KEYS[KEY_NAMES[i]] = PREFIX_OLD ? PREFIX_OLD + KEY_NAMES[i] : '';
    }

